import gzip,re,glob
pat=re.compile(r'[^\t"]{0,60}\b\d[\d.,]*\s*(?:[pnuµμmM]?M|mol|mg/ml|ng/ml|µg|ug/ml)\b[^\t"]{0,40}',re.I)
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    s=set()
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        for m in pat.findall(l): s.add(m.strip())
    for x in sorted(s): print('  ',x)
